namespace ghidra.app.plugin.core.compositeeditor;







using docking;
using docking.action;
using generic.theme;
using ghidra.util.exception;
using ghidra.util.task;

/**
 * Action to duplicate the selected row
 */
public class DuplicateAction : CompositeEditorTableAction {

	private static Icon ICON = new GIcon("icon.plugin.composite.editor.duplicate");
	public static string ACTION_NAME = "Duplicate Component";
	private static string GROUP_NAME = COMPONENT_ACTION_GROUP;
	private static string DESCRIPTION = "Duplicate the selected component";
	private static string[] POPUP_PATH = new string[] { ACTION_NAME };
	private static KeyStroke KEY_STROKE =
		KeyStroke.getKeyStroke(KeyEvent.VK_D, InputEvent.ALT_DOWN_MASK);

	public DuplicateAction(CompositeEditorProvider<object,object> provider) : base(provider, ACTION_NAME, GROUP_NAME, POPUP_PATH, null, ICON)
    {
		setDescription(DESCRIPTION);
		setKeyBindingData(new KeyBindingData(KEY_STROKE));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!isEnabledForContext(context)) {
			return;
		}
		int[] indices = model.getSelectedComponentRows();
		if (indices.length != 1) {
			return;
		}

		int max = model.getMaxDuplicates(indices[0]);
		if (max != 0) {
			try {
				// note: only duplicating one item; no need for a task
				model.duplicateMultiple(indices[0], 1, TaskMonitor.DUMMY);
			}
			catch (UsrException e1) {
				model.setStatus(e1.getMessage(), true);
			}
		}
		requestTableFocus();
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return !hasIncompleteFieldEntry() && model.isDuplicateAllowed();
	}

}
